// Parsear resultado XML de Nmap SIN dependencias externas (solo regex nativo)
const xmlData = $input.first().json.stdout;

// CORRECCIÓN CRÍTICA: Se exige un espacio o el cierre del tag para evitar las etiquetas <hosthint>
const hostBlocks = xmlData.match(/<host(?: [^>]+)?>[\s\S]*?<\/host>/g) || [];

const hosts = hostBlocks.map(block => {
  const ipMatch = block.match(/<address addr="([^"]+)" addrtype="ipv4"/);
  const stateMatch = block.match(/<status state="([^"]+)"/);
  const hostnameMatch = block.match(/<hostname name="([^"]+)"/);
  const osMatch = block.match(/<osmatch name="([^"]+)"/);

  const portMatches = block.match(/<port protocol="(\w+)" portid="(\d+)">[\s\S]*?<\/port>/g) || [];

  const ports = portMatches.map(portBlock => {
    const protocol = portBlock.match(/protocol="(\w+)"/)?.[1] || '';
    const portid = portBlock.match(/portid="(\d+)"/)?.[1] || '';
    const portState = portBlock.match(/<state state="([^"]+)"/)?.[1] || '';
    const serviceName = portBlock.match(/<service name="([^"]*)"/)?.[1] || 'unknown';
    const serviceVersion = portBlock.match(/version="([^"]*)"/)?.[1] || '';

    return {
      port: portid,
      protocol: protocol,
      state: portState,
      service: serviceName,
      version: serviceVersion
    };
  });

  return {
    ip: ipMatch ? ipMatch[1] : 'Unknown',
    hostname: hostnameMatch ? hostnameMatch[1] : 'Unknown',
    state: stateMatch ? stateMatch[1] : 'Unknown',
    os: osMatch ? osMatch[1] : 'Unknown',
    ports: ports
  };
});

// Retornar la estructura de elementos JSON requerida por n8n
return hosts.map(host => ({ json: host }));

// Obtener todos los hosts descubiertos por Nmap
const items = $input.all();

// Filtrar hosts activos ('up') con IP valida (sin IPs hardcodeadas)
const activeHosts = items
  .map(item => item.json)
  .filter(h => h && h.state === 'up' && h.ip && h.ip !== 'Unknown');

const ips = activeHosts.map(h => h.ip);

if (ips.length === 0) {
  throw new Error('Nmap no encontro ningun host activo en la red.');
}

// 1. Cadena de hosts separados por coma para OpenVAS
const hostsArg = ips.join(',');

// 2. Extraer puertos abiertos encontrados por Nmap en los hosts activos
const allPorts = new Set();
activeHosts.forEach(h => {
  if (Array.isArray(h.ports)) {
    h.ports.forEach(p => {
      if (p.state === 'open' && p.port) {
        allPorts.add(p.port);
      }
    });
  }
});

const portsArg = allPorts.size > 0
  ? Array.from(allPorts).sort((a, b) => parseInt(a) - parseInt(b)).join(',')
  : '22,80,443,5678,8080';

return [{
  json: {
    hostsArg,
    portsArg,
    host_count: ips.length,
    active_hosts: ips
  }
}];

// Parsear resultado XML de OpenVAS SIN dependencias externas
const inputJson = $input.first().json;

// 1. VALIDADOR DE ENTRADA: Detiene el flujo si no viene el XML desde OpenVAS
if (!inputJson.stdout) {
  throw new Error("ERROR: No se encontró el campo 'stdout'. Asegúrate de que el nodo esté conectado a la salida del nodo SSH y de ejecutar el nodo SSH primero.");
}

const xmlData = inputJson.stdout;

// 2. Extraer Fecha de inicio del escaneo
const scanDateMatch = xmlData.match(/<scan_start>([^<]+)<\/scan_start>/);
const scanDate = scanDateMatch ? scanDateMatch[1] : new Date().toISOString();

// 3. Extraer bloques individuales de resultados
const resultBlocks = xmlData.match(/<result id="[^"]+">[\s\S]*?<\/result>/g) || [];

// Función auxiliar para limpiar entidades XML
const decodeXML = (str) => {
  if (!str) return '';
  return str
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&');
};

// 4. Mapeo de datos
const vulnerabilities = resultBlocks.map(block => {
  const nameMatch = block.match(/<name>([^<]+)<\/name>/);
  const hostMatch = block.match(/<host>([^<]+)</); 
  const portMatch = block.match(/<port>([^<]+)<\/port>/);
  const severityMatch = block.match(/<severity>([^<]+)<\/severity>/);
  const threatMatch = block.match(/<threat>([^<]+)<\/threat>/);
  const descMatch = block.match(/<description>([\s\S]*?)<\/description>/);
  const solMatch = block.match(/<solution[^>]*>([\s\S]*?)<\/solution>/);

  // Extraer CVEs si existen
  const cveMatches = [...block.matchAll(/<ref type="cve" id="([^"]+)"\/>/g)].map(m => m[1]);

  return {
    name: nameMatch ? decodeXML(nameMatch[1].trim()) : 'Unknown',
    host: hostMatch ? hostMatch[1].trim() : 'Unknown',
    port: portMatch ? portMatch[1].trim() : 'Unknown',
    severity: severityMatch ? parseFloat(severityMatch[1]) : 0.0,
    threat: threatMatch ? threatMatch[1].trim() : 'Log',
    description: descMatch ? decodeXML(descMatch[1].trim()) : '',
    solution: solMatch ? decodeXML(solMatch[1].trim()) : '',
    cve: cveMatches.length > 0 ? cveMatches.join(', ') : ''
  };
});

// 5. Retorno estructurado
return [{
  json: {
    scanDate: scanDate,
    vulnerabilities: vulnerabilities
  }
}];

// Aplanar vulnerabilidades a items individuales para insertar en DB
const data = $input.first().json;
const vulnerabilities = data.vulnerabilities;

return vulnerabilities.map(vuln => ({
  json: {
    scan_date: data.scanDate,
    host: vuln.host,
    vulnerability_name: vuln.name,
    severity: vuln.severity,
    port: vuln.port,
    cve: vuln.cve,
    description: vuln.description,
    solution: vuln.solution
  }
}));

const data = $('Parse Results').first().json;
const vulns = data.vulnerabilities || [];

const critical = vulns.filter(v => v.severity >= 9.0);
const high = vulns.filter(v => v.severity >= 7.0 && v.severity < 9.0);
const medium = vulns.filter(v => v.severity >= 4.0 && v.severity < 7.0);
const low = vulns.filter(v => v.severity < 4.0); // Incluye severidad 0 (Informativas)

const pct = (n) => vulns.length ? ((n / vulns.length) * 100).toFixed(1) : '0.0';

// Función auxiliar para renderizar los bloques de vulnerabilidades y no repetir código
const renderVulns = (vulnArray, title, limit = 30) => {
  if (vulnArray.length === 0) return `*No se encontraron vulnerabilidades ${title.toLowerCase()}.*\n`;

  let section = '';
  const visible = vulnArray.slice(0, limit);

  section += visible.map((v, i) => `
### ${i+1}. ${v.name}

**Host**: ${v.host}:${v.port}
**Severidad**: ${v.severity}/10.0
**CVE**: ${v.cve || 'N/A'}

**Descripcion**:
${v.description ? (v.description.length > 300 ? v.description.substring(0, 300) + '...' : v.description) : '*Sin descripción.*'}

**Solucion Recomendada**:
${v.solution ? (v.solution.length > 300 ? v.solution.substring(0, 300) + '...' : v.solution) : '*Sin solución especificada.*'}

---
`).join('\n');

  // Si hay más vulnerabilidades que el límite, agregamos un aviso
  if (vulnArray.length > limit) {
    section += `*...y ${vulnArray.length - limit} vulnerabilidades ${title.toLowerCase()} adicionales.*\n`;
  }

  return section;
};

const report = `
# Informe de Escaneo de Vulnerabilidades

**Fecha del Escaneo**: ${new Date(data.scanDate).toLocaleString('es-AR')}
**Hosts Escaneados**: ${[...new Set(vulns.map(v => v.host))].length}
**Total de Vulnerabilidades**: ${vulns.length}

---

## Resumen Ejecutivo

| Severidad | Cantidad | Porcentaje |
|-----------|----------|------------|
| Crítica (9.0-10.0) | ${critical.length} | ${pct(critical.length)}% |
| Alta (7.0-8.9) | ${high.length} | ${pct(high.length)}% |
| Media (4.0-6.9) | ${medium.length} | ${pct(medium.length)}% |
| Baja e Informativa (0.0-3.9) | ${low.length} | ${pct(low.length)}% |

---

## Vulnerabilidades Críticas
${renderVulns(critical, 'críticas', 10)}

## Vulnerabilidades Altas
${renderVulns(high, 'altas', 10)}

## Vulnerabilidades Medias
${renderVulns(medium, 'medias', 20)}

## Vulnerabilidades Bajas e Informativas
${renderVulns(low, 'bajas e informativas', 30)}

## Recomendaciones Generales

1. Priorizar la remediación de vulnerabilidades críticas y altas inmediatamente.
2. Aplicar parches de seguridad para mitigar las vulnerabilidades de severidad media (como la transmisión de credenciales FTP en texto claro).
3. Revisar los hallazgos bajos e informativos (ej. banners expuestos, métodos HTTP permitidos) para reducir la superficie de ataque y mejorar el bastionado (hardening) de los servidores.
4. Implementar políticas de actualización regular.
5. Realizar escaneos de seguimiento después de aplicar correcciones.

---

## Hosts Analizados

${[...new Set(vulns.map(v => v.host))].map(host => {
  const hostVulns = vulns.filter(v => v.host === host);
  return `
### ${host}
- Total vulnerabilidades: ${hostVulns.length}
- Críticas: ${hostVulns.filter(v => v.severity >= 9.0).length}
- Altas: ${hostVulns.filter(v => v.severity >= 7.0 && v.severity < 9.0).length}
- Medias: ${hostVulns.filter(v => v.severity >= 4.0 && v.severity < 7.0).length}
- Bajas/Informativas: ${hostVulns.filter(v => v.severity < 4.0).length}
`;
}).join('\n')}

---

*Informe generado automáticamente por el sistema de escaneo de vulnerabilidades*
`;

return [{
  json: {
    report: report,
    scanDate: data.scanDate,
    summary: {
      total: vulns.length,
      critical: critical.length,
      high: high.length,
      medium: medium.length,
      low: low.length
    }
  }
}];
